def add_heading(doc, text, size, colour=None, bold=True, centre=False):
    p = doc.add_paragraph()
    if centre:
        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    r = p.add_run(text)
    r.bold = bold
    r.font.size = Pt(size)
    if colour is not None:
        r.font.color.rgb = colour
    return p


def main():
    doc = Document()
    style = doc.styles['Normal']
    style.font.name = 'Times New Roman'
    style.font.size = Pt(11)

    add_heading(doc, 'Reviewer Comments and Author Responses - Round 2 (Consolidated)',
                16, centre=True)
    p = doc.add_paragraph()
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    r = p.add_run('Manuscript: Vehicle-to-Vehicle Communication for Blind Spot '
                  'Detection and Accident Prevention Using Severity-Gated '
                  'Collision Risk Indexing')
    r.italic = True
    r.font.size = Pt(10)
    p = doc.add_paragraph()
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    r = p.add_run('Corresponding author: Deepali Vora (deepali.vora11@sitpune.edu.in)   |   14 August 2026')
    r.font.size = Pt(10)
    r.font.color.rgb = GREY
    doc.add_paragraph()

    add_heading(doc, 'Summary of global changes in this revision', 12)
    doc.add_paragraph(PREAMBLE)
    doc.add_paragraph()

    for reviewer in ['Reviewer 1', 'Reviewer 2', 'Reviewer 4']:
        add_heading(doc, reviewer, 15, colour=BLUE)

        add_heading(doc, 'Original comments (Round 2, verbatim):', 12)
        for block in COMMENTS[reviewer].strip().split('\n\n'):
            doc.add_paragraph(block.strip())
        doc.add_paragraph()

        add_heading(doc, 'Author responses:', 12)
        for title, quoted, response, change in RESPONSES[reviewer]:
            add_heading(doc, title, 11.5)
            p = doc.add_paragraph()
            r = p.add_run('Reviewer comment: ')
            r.bold = True
            r = p.add_run(quoted)
            r.italic = True
            p = doc.add_paragraph()
            r = p.add_run('Response: ')
            r.bold = True
            p.add_run(response)
            p = doc.add_paragraph()
            r = p.add_run('Manuscript change: ')
            r.bold = True
            p.add_run(change)
            doc.add_paragraph()

        sep = doc.add_paragraph('-' * 60)
        sep.alignment = WD_ALIGN_PARAGRAPH.CENTER
        doc.add_paragraph()

    OUT.parent.mkdir(parents=True, exist_ok=True)
    doc.save(str(OUT))
    print(f'wrote: {OUT}')


if __name__ == '__main__':
    main()
